package com.azyabon.weatherapp.fragments.home

import android.Manifest
import android.app.AlertDialog
import android.content.pm.PackageManager
import android.location.Geocoder
import android.os.Bundle
import android.view.LayoutInflater
import android.view.View
import android.view.ViewGroup
import android.widget.Toast
import androidx.activity.result.contract.ActivityResultContracts
import androidx.core.content.ContextCompat
import androidx.fragment.app.Fragment
import androidx.navigation.fragment.findNavController
import com.azyabon.weatherapp.data.CurrentLocation
import com.azyabon.weatherapp.databinding.FragmentHomeBinding
import com.azyabon.weatherapp.storage.SharedPreferencesManager
import com.google.android.gms.location.LocationServices
import org.koin.android.ext.android.inject
import org.koin.androidx.viewmodel.ext.android.viewModel

class HomeFragment : Fragment() {

 private var _binding: FragmentHomeBinding? = null
 private val binding get() = requireNotNull(_binding)

 private val homeViewModel: HomeViewModel by viewModel()
 private val fusedLocationProviderClient by lazy {
 LocationServices.getFusedLocationProviderClient(requireContext())
 }
 private val geocoder by lazy { Geocoder(requireContext()) }

 private val weatherDataAdapter = WeatherDataAdapter(
 onLocationClicked = { showLocationOptions() }
 )

 private val sharedPreferencesManager: SharedPreferencesManager by inject()

 private val locationPermissionLauncher = registerForActivityResult(
 ActivityResultContracts.RequestPermission()
 ) { isGranted ->
 if (isGranted) {
 getCurrentLocation()
 } else {
 Toast.makeText(requireContext(), "Permission denied", Toast.LENGTH_SHORT).show()
 }
 }

 override fun onCreateView(
 inflater: LayoutInflater,
 container: ViewGroup?,
 savedInstanceState: Bundle?
 ): View {
 _binding = FragmentHomeBinding.inflate(inflater, container, false)

 return binding.root
 }

 override fun onViewCreated(view: View, savedInstanceState: Bundle?) {
 super.onViewCreated(view, savedInstanceState)
 setWeatherDataAdapter()
 setWeatherData(currentLocation = sharedPreferencesManager.getCurrentLocation())
 setObservers()
 }

 private fun setObservers() {
 with(homeViewModel) {
 currentLocation.observe(viewLifecycleOwner) {
 val currentLocationDataState = it ?: return@observe

 if (currentLocationDataState.isLoading) {
 showLoading()
 }

 currentLocationDataState.currentLocationData?.let { currentLocation ->
 hideLoading()
 sharedPreferencesManager.saveCurrentLocation(currentLocation)
 setWeatherData(currentLocation)
 }
 currentLocationDataState.error?.let { error ->
 hideLoading()
 Toast.makeText(requireContext(), error, Toast.LENGTH_SHORT).show()
 }
 }
 }
 }

 private fun setWeatherDataAdapter() {
 binding.rvWeatherData.adapter = weatherDataAdapter
 }

 private fun setWeatherData(currentLocation: CurrentLocation? = null) {
 weatherDataAdapter.setData(data = listOf(currentLocation ?: CurrentLocation()))
 }

 private fun getCurrentLocation() {
 homeViewModel.getCurrentLocation(fusedLocationProviderClient, geocoder)
 }

 private fun isLocationPermissionGranted(): Boolean {
 return ContextCompat.checkSelfPermission(
 requireContext(),
 Manifest.permission.ACCESS_FINE_LOCATION
 ) == PackageManager.PERMISSION_GRANTED
 }

 private fun requestLocationPermission() {
 locationPermissionLauncher.launch(Manifest.permission.ACCESS_FINE_LOCATION)
 }

 private fun proceedWithCurrentLocation() {
 if (isLocationPermissionGranted()) {
 getCurrentLocation()
 } else {
 requestLocationPermission()
 }
 }

 private fun showLocationOptions() {
 val options = arrayOf("Current Location", "Search Manually")
 AlertDialog.Builder(requireContext()).apply {
 setTitle("Choose Location")
 setItems(options) { _, which ->
 when (which) {
 0 -> proceedWithCurrentLocation()
 }
 }
 show()
 }
 }

 private fun showLoading() {
 with(binding) {
 rvWeatherData.visibility = View.GONE
 srLayout.isRefreshing = true
 }
 }

 private fun hideLoading() {
 with(binding) {
 rvWeatherData.visibility = View.VISIBLE
 srLayout.isRefreshing = false
 }
 }

 private fun startManualLocationSearch() {
 findNavController().navigate(R.id.action_home_fragment_to_location_fragment)
 }
}
